  this.timber(s,10,1.7,1.0,0,.48,-6.6,0x633c20);this.timber(s,10.4,.18,1.5,0,1.42,-6.4,0x3f281a);for(let x=-4.8;x<=4.8;x+=.4)this.timber(s,.05,1.55,.06,x,.53,-6.07,0x34231a);
