  for(let i=1;i<this.seatCount;i++){const p=this.seatPoint(i),cx=p.x/1.25,cz=p.z/1.4;this.seatLines.push({mesh:line([[cx-.5,cz-.32],[cx+.5,cz-.32],[cx+.5,cz+.32],[cx-.5,cz+.32]]),seat:i,cx,cz})}
