 chip(parent,x,y,z,color){const inPot=!this.isBlackjackTable&&this.mode==='poker'&&parent===this.chipPiles&&Math.abs(z+1.6)<.01;if(inPot){x*=.5;z=-1.72;y=1.41+(y-1.38)*.5}if(color===0xc2b46c)color=[0xad473c,0x41649b,0x855c38,0xc6b27b][Math.abs(Math.round(y/.055))%4];const g=super.chip(parent,x,y,z,color);if(inPot)g.scale.setScalar(.5);g.children[0].material=this.surface('clay',color??0xb77f4e);const key='chip-print-'+color;if(!this.textures.has(key)){const labels=[11,4,3,5],n=labels[Math.abs((color??0)>>8)%4];this.textures.set(key,this.textTexture(String(n),'#e9d9b0','#65452d',96,96))}const face=new T.Mesh(new T.PlaneGeometry(.10,.10),new T.MeshStandardMaterial({map:this.textures.get(key),roughness:.9}));face.rotation.x=-Math.PI/2;face.position.y=.031;g.add(face);return g}
 sync(view,options){super.sync(view,options);if(this.potProp){const narrow=this.container.clientWidth<=600;this.potProp.position.set(narrow?3.25:0,1.34,narrow?1.65:-1.72);this.potProp.scale.setScalar(narrow?.42:.6);this.potProp.visible=!view.done&&!view.runout&&view.pot>0;for(const area of this.seatLines??[]){const p=this.seatPoint(area.seat);area.mesh.position.set(p.x/1.25-area.cx,0,p.z/1.4-area.cz)}}if(this.dealerPlaque){const seat=Number.isInteger(view.dealer)?view.dealer:0,p=this.chipPoint(seat);this.dealerPlaque.position.set(p.x+(p.x>0?-.55:.55),1.39,p.z+.26);this.dealerPlaque.visible=!view.done&&!view.runout}}
 animateEffects(time){super.animateEffects(time);if(this.voxelDust&&!this.reduced)this.voxelDust.position.y=Math.sin(time*.25)*.08;for(const [i,f] of (this.torchFlames??[]).entries())f.material.emissiveIntensity=1.8+(this.reduced?0:Math.sin(time*3+i)*.2);for(const rig of this.backgroundRigs??[])this.animateRig(rig,time,.016)}
 reflections(){const room=new T.Scene();room.background=new T.Color(0x352919);for(const [x,y,z,w,h,d,c] of [[-3,6,2,3,.1,4,0xffdb9d],[4,4,-4,1,3,.1,0x977253],[0,5,-5,5,.1,1,0xe5b775]]){const b=new T.Mesh(new T.BoxGeometry(w,h,d),new T.MeshBasicMaterial({color:c}));b.position.set(x,y,z);room.add(b)}const pmrem=new T.PMREMGenerator(this.renderer);this.tavernEnv=pmrem.fromScene(room,.12);this.scene.environment=this.tavernEnv.texture;this.scene.environmentIntensity=.32;pmrem.dispose();room.traverse(o=>{o.geometry?.dispose();o.material?.dispose()})}
 destroy(){this.tavernEnv?.dispose();super.destroy()}
